import {createWork} from './work.js';
import {createWealth} from './wealth.js';
import {createStudio} from './studio.js';
const $=(s,r=document)=>r.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',cases:'M3 7h18v14H3z M8 7V3h8v4 M3 12h18',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M17 4a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.9',file:'M14 2H5v20h14V7z M14 2v6h5 M8 12h8 M8 16h6',flow:'M9 2h6v6H9z M2 16h6v6H2z M16 16h6v6h-6z M12 8v4 M5 16v-4h14v4',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6z M8 12l3 3 5-6',chart:'M4 3v18h17 M8 16v-5 M13 16V7 M18 16V4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',search:'M21 21l-5-5 M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',plus:'M12 5v14 M5 12h14',chevron:'M9 5l7 7-7 7',down:'m6 9 6 6 6-6',arrow:'M4 12h16 M14 6l6 6-6 6',clock:'M12 8v5l3 2 M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20',check:'m5 12 4 4L19 6',close:'m6 6 12 12 M6 18 18 6',upload:'M12 16V3 M7 8l5-5 5 5 M3 15v6h18v-6',download:'M12 3v13 M7 11l5 5 5-5 M3 17v4h18v-4',globe:'M2 12h20 M12 2c-6 5-6 15 0 20 6-5 6-15 0-20 M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20',help:'M9 8a3 3 0 0 1 6 0c0 2-3 2-3 5 M12 17h.01 M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20',flag:'M5 22V3c5-4 9 4 15 0v10c-6 4-10-4-15 0',refresh:'M21 8a9 9 0 1 0 0 8 M21 2v6h-6',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z',lock:'M5 10h14v12H5z M8 10V6a4 4 0 0 1 8 0v4'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.file}"/></svg>`;
let state,page='Overview',query='',stageFilter='All stages',riskFilter='All risks',activeCase=null,tab='Overview',mode='list';
const nav=[['Overview','grid'],['Work queue','clock'],['Onboarding','cases'],['Client directory','users'],['Document centre','file'],['Source of wealth','chart'],['Workflows','flow'],['Rules & policies','shield'],['Reports & insights','chart']];
const money=n=>new Intl.NumberFormat('en-SG',{style:'currency',currency:'SGD',notation:'compact',maximumFractionDigits:1}).format(n*1e6),date=s=>new Date(s).toLocaleDateString('en-SG',{day:'2-digit',month:'short',year:'numeric'}),initials=n=>n.split(' ').slice(0,2).map(x=>x[0]).join('');
const badge=(t,col='')=>`<span class="badge ${col||({Low:'green',Medium:'amber',High:'red',Verified:'green',Rejected:'red','Pending review':'amber',Active:'green',Approval:'purple',Documentation:'blue','Due diligence':'amber','Periodic review':'purple',Offboarded:'gray',Prospect:'gray'}[t]||'blue')}"><i></i>${esc(t)}</span>`;
const btn=(t,a,i='',cl='secondary')=>`<button class="btn ${cl}" data-action="${a}">${i?icon(i):''}${t}</button>`,client=()=>state.session.role==='Client',opened=()=>state.cases.filter(c=>!['active','closed'].includes(c.stageKind)),days=c=>Math.floor((new Date(c.dueDate+'T23:59:59')-new Date())/864e5),verified=c=>c.requiredDocuments.filter(t=>c.documents.some(d=>d.type===t&&d.status==='Verified')).length,progress=c=>Math.round(verified(c)/c.requiredDocuments.length*100);
async function api(url,method='GET',data){const r=await fetch('/api'+url,{method,headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const b=await r.json();if(!r.ok)throw Error(b.error||'Request failed');return b;}
const wealth=createWealth({state:()=>state,esc,icon,btn,badge,heading,modal,closeModal,toast,api,mutate,render,navigate:n=>{page=n;render();},requestFollowup:(id,title,category)=>work.create(id,title,category),documents:id=>{activeCase=id;tab='Documents';caseModal();}});
const work=createWork({state:()=>state,esc,icon,btn,badge,heading,modal,closeModal,toast,mutate,render,openWealth:(id,section)=>wealth.open(id,section),openCase:(id,section)=>{activeCase=id;tab=section;if(client()){page='Client portal';render();}else caseModal();}});
const studio=createStudio({state:()=>state,esc,icon,btn,badge,heading,modal,closeModal,toast,api,mutate});
async function load(){state=await api('/state');if(client())page='Client portal';render();}
function toast(t,error=false){const e=$('#toast');e.textContent=t;e.className='show'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.className='',5000);}
function heading(eyebrow,title,sub,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div><div class="heading-actions">${actions}</div></div>`;}
function render(){document.documentElement.style.setProperty('--blue',state.ui.accent);document.body.dataset.density=state.ui.density;document.title=page+' • Aurelia CLM';$('#app').innerHTML=`<aside class="sidebar"><a href="#" class="brand"><span class="brand-symbol">A<span>✦</span></span><span>${esc(state.ui.brand)}<small>CLIENT LIFECYCLE MANAGEMENT</small></span></a><div class="workspace"><span class="workspace-logo">${icon('globe')}</span><div>Private Banking<small>Singapore workspace</small></div><span class="live-dot"></span></div><div class="nav-label">WORKSPACE</div><nav>${(client()?[['Client portal','users']]:nav.filter(([n])=>(['Source of wealth','Work queue'].includes(n)||state.ui.navigation.includes(n)))).map(([n,i])=>`<button data-page="${n}" aria-label="${n}" title="${n}" class="nav-item ${page===n?'selected':''}">${icon(i)}<span>${n}</span>${n==='Onboarding'?`<b>${opened().length}</b>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="help-card">${icon('spark')}<strong>Better journeys. Together.</strong><p>One connected workspace for every client relationship.</p><button data-action="help">Explore the workspace ${icon('arrow')}</button></div>${!client()?`<button class="nav-item ${page==='Settings'?'selected':''}" data-page="Settings" aria-label="Workspace settings" title="Workspace settings">${icon('settings')}<span>Workspace settings</span></button>`:''}<button class="nav-item" data-action="help" aria-label="Help and resources" title="Help and resources">${icon('help')}<span>Help & resources</span></button><div class="sidebar-foot"><span class="live-dot"></span> Synthetic demo workspace <span>v3.0</span></div></div></aside><div class="app-main"><header class="topbar"><div class="breadcrumb">Workspace ${icon('chevron')} <strong>${esc(page)}</strong></div><div class="top-actions">${!client()?`<button class="icon-btn" aria-label="Find a relationship" data-action="work:search">${icon('search')}</button>`:''}<span class="region">${icon('globe')} Singapore <span>SGT</span></span><button class="icon-btn notification" aria-label="View attention queue" data-action="notifications">${icon('bell')}<i></i></button><span class="top-divider"></span><button class="profile" data-action="switch-role"><span class="avatar">${client()?initials(state.cases[0].name):state.session.role==='Compliance'?'AC':state.session.role==='Operations'?'ML':'SC'}</span><span>${client()?esc(state.cases[0].name):state.session.role==='Compliance'?'Alex Chua':state.session.role==='Operations'?'Maya Lee':'Sarah Chen'}<small>${esc(state.session.role)} · Demo</small></span>${icon('down')}</button></div></header><main>${({Overview:dashboard,'Work queue':()=>work.page(),Onboarding:onboarding,'Client directory':clients,'Document centre':documentsPage,'Source of wealth':()=>wealth.workspace(),Workflows:workflows,'Rules & policies':rulesPage,'Reports & insights':reports,Settings:settings,'Client portal':portal}[page])()}</main><footer><span>© 2026 Aurelia · Private banking, thoughtfully connected.</span><span>${icon('lock')} Demo data only · Singapore booking centre</span></footer></div>`;bind();}
function stats(){const o=opened(),d=o.filter(c=>days(c)<=3);return `<div class="stats-grid">${[['Open lifecycle cases',o.length,`${state.cases.length} total relationships`,'cases','blue','Across the client lifecycle'],['Awaiting approval',state.cases.filter(c=>c.stageKind==='approval').length,'Ready for a compliance decision','shield','purple','Keep client journeys moving'],['Needs attention',d.length,'Cases due within 3 days','clock','amber',`${d.filter(c=>days(c)<0).length} past the target date`],['Relationship assets',money(state.cases.reduce((a,c)=>a+c.aum,0)),`${state.cases.filter(c=>c.stageKind==='active').length} active client relationships`,'chart','green','Indicative assets · SGD']].map(([l,v,s,i,col,f])=>`<section class="stat-card"><div class="stat-top"><span>${l}</span><span class="stat-icon ${col}">${icon(i)}</span></div><div class="stat-value">${v}</div><div class="stat-sub">${s}</div><div class="stat-foot"><span class="mini-dot ${col}"></span>${f}</div></section>`).join('')}</div>`;}
function dashboard(){const total=opened().reduce((a,c)=>a+c.requiredDocuments.length,0),ready=opened().reduce((a,c)=>a+verified(c),0),pending=opened().reduce((a,c)=>a+c.requiredDocuments.filter(t=>!c.documents.some(d=>d.type===t&&d.status==='Verified')&&c.documents.some(d=>d.type===t&&d.status==='Pending review')).length,0),p=Math.round(ready/Math.max(1,total)*100);return heading('YOUR WORKSPACE, AT A GLANCE',esc(state.ui.heading),esc(state.ui.subtitle),btn('Export report','export','download')+btn('New onboarding','new-case','plus','primary'))+`<div class="welcome-strip"><div><span class="greeting-icon">${icon('spark')}</span><span><strong>Good ${new Date().getHours()<12?'morning':'afternoon'}, ${state.session.role==='Compliance'?'Alex':state.session.role==='Operations'?'Maya':'Sarah'}.</strong> You have <b>${state.cases.filter(c=>c.stageKind==='approval').length} cases ready for approval</b>. Let’s make progress.</span></div><button data-page="Onboarding">View your work ${icon('arrow')}</button></div>`+stats()+work.summary()+`<div class="wealth-quick">${icon('chart')}<div><strong>Wealth intelligence, connected to every relationship.</strong><p>${state.cases.filter(c=>c.wealthSummary?.status==='In review').length} awaiting wealth review · ${state.cases.filter(c=>c.wealthSummary?.status==='Needs refresh').length} assessments need refreshing</p></div><button class="btn secondary" data-page="Source of wealth">Open wealth workspace ${icon('arrow')}</button></div><div class="overview-middle"><section class="panel pipeline-panel"><div class="panel-heading"><div><h2>Onboarding pipeline</h2><p>From first conversation to lasting relationship</p></div><span class="subtle-pill">${opened().filter(c=>c.stage!=='Periodic review').length} onboarding</span></div><div class="pipeline">${state.workflow.stages.filter(s=>s.kind!=='closed').map(s=>s.name).map((s,i)=>{const n=state.cases.filter(c=>c.stage===s).length;return `<button class="pipeline-step" data-stage="${esc(s)}"><span class="pipeline-top"><span class="step-icon s${i}">${icon(['users','file','shield','check','flag'][i%5])}</span>${i<4?icon('chevron'):''}</span><strong>${String(n).padStart(2,'0')}</strong><span>${esc(s)}</span><div class="pipeline-bar"><i style="width:${Math.max(12,n/state.cases.length*220)}%;background:${['#8eabd3','#528ce4','#e8b758','#9a88d5','#4aa590'][i%5]}"></i></div></button>`}).join('')}</div><div class="panel-caption">${icon('flow')} A clear owner at every step. <button data-page="Workflows">View workflow ${icon('arrow')}</button></div></section><section class="panel health-panel"><div class="panel-heading"><div><h2>Document readiness</h2><p>Across active onboarding cases</p></div>${icon('file')}</div><div class="health-content"><div class="donut" style="--value:${p};--pending:${Math.round((ready+pending)/Math.max(1,total)*100)}"><div><strong>${p}%</strong><span>verified</span></div></div><div class="legend"><span><i class="dot blue"></i>Verified <b>${ready}</b></span><span><i class="dot pale"></i>Pending review <b>${pending}</b></span><span><i class="dot light"></i>Missing <b>${total-ready-pending}</b></span></div></div><div class="health-bottom">A complete file. A smoother start. ${icon('check')}</div></section></div><div class="overview-bottom"><section class="panel cases-panel"><div class="panel-heading"><div><h2>Your onboarding cases <span class="count">${opened().length}</span></h2><p>The relationships moving through your workspace</p></div><button class="text-btn" data-page="Onboarding">View all cases ${icon('arrow')}</button></div>${caseTable(opened().slice(0,5),true)}</section><section class="panel activity-panel"><div class="panel-heading"><div><h2>Recent activity</h2><p>Every step, in the loop</p></div><span class="live-dot"></span></div>${activities(4)}<div class="activity-foot">${icon('clock')} Times shown in your local timezone</div></section></div>`;}
function activities(n,c=null){const all=(c?c.activity:state.cases.flatMap(c=>c.activity.map(a=>({...a,client:c.name,caseId:c.id})))).sort((a,b)=>b.at.localeCompare(a.at)).slice(0,n);return `<div class="timeline">${all.map((a,i)=>`<div class="timeline-item"><div class="timeline-point ${i===0?'blue':''}">${icon(i===0?'check':'file')}</div><div><strong>${esc(a.action)}</strong>${a.client?`<button class="activity-client" data-case="${a.caseId}">${esc(a.client)}</button>`:''}${a.note?`<p>${esc(a.note)}</p>`:''}<small>${esc(a.actor)} · ${new Date(a.at).toLocaleString('en-SG',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</small></div></div>`).join('')}</div>`;}
function caseTable(list,compact=false){return `<div class="table-wrap"><table><thead><tr><th>Client / Case ID</th><th>Stage</th><th>Risk</th>${compact?'':'<th>Relationship manager</th><th>Assets (SGD)</th>'}<th>Documents</th><th>Due date</th><th></th></tr></thead><tbody>${list.map((c,i)=>`<tr data-case="${c.id}" tabindex="0" role="button" aria-label="Open ${esc(c.name)}"><td><div class="client-cell"><span class="avatar client-avatar tint${i%4}">${initials(c.name)}</span><div><strong>${esc(c.name)}</strong><small>${c.id}</small></div></div></td><td>${badge(c.stage)}</td><td>${badge(c.risk)}</td>${compact?'':`<td>${esc(c.owner)}</td><td>${money(c.aum)}</td>`}<td><div class="doc-progress"><span>${verified(c)}<small> / ${c.requiredDocuments.length}</small></span><div><i style="width:${progress(c)}%"></i></div></div></td><td><span class="${days(c)<0?'overdue':''}">${date(c.dueDate).replace(' 2026','')}</span>${days(c)<0?'<small class="overdue">Overdue</small>':''}</td><td>${icon('chevron')}</td></tr>`).join('')||'<tr><td colspan="8"><div class="empty">No cases match your filters.</div></td></tr>'}</tbody></table></div>`;}
function filtered(){return state.cases.filter(c=>(stageFilter==='All stages'||c.stage===stageFilter)&&(riskFilter==='All risks'||c.risk===riskFilter)&&`${c.name} ${c.id} ${c.owner}`.toLowerCase().includes(query.toLowerCase()));}
function filters(){return `<div class="filter-bar"><label class="search-input">${icon('search')}<input id="case-search" placeholder="Search clients, case IDs or owners…" value="${esc(query)}"></label><div class="filter-right"><select id="stage-filter" aria-label="Filter by stage">${['All stages',...state.stages].map(s=>`<option ${stageFilter===s?'selected':''}>${esc(s)}</option>`).join('')}</select><select id="risk-filter" aria-label="Filter by risk">${['All risks','Low','Medium','High'].map(s=>`<option ${riskFilter===s?'selected':''}>${esc(s)}</option>`).join('')}</select><button class="icon-btn" data-action="reset-filters" aria-label="Reset filters">${icon('refresh')}</button></div></div>`;}
function board(list){return `<div class="kanban">${state.stages.filter(s=>s!=='Offboarded').map(s=>`<div class="kanban-col"><div class="kanban-head">${esc(s)}<span>${list.filter(c=>c.stage===s).length}</span></div>${list.filter(c=>c.stage===s).map(c=>`<button class="kanban-card" data-case="${c.id}"><small>${c.id}</small><strong>${esc(c.name)}</strong><p>${esc(c.owner)}</p>${badge(c.risk)}<div class="kanban-bottom">${money(c.aum)} ${icon('arrow')}</div></button>`).join('')||'<p class="muted">No cases</p>'}</div>`).join('')}</div>`;}
function onboarding(){return heading('CLIENT LIFECYCLE','Onboarding workspace','Orchestrate every step. Keep every relationship moving.',btn('New onboarding','new-case','plus','primary'))+stats()+`<section class="panel"><div class="tabs"><button class="tab ${mode==='list'?'active':''}" data-mode="list">All cases <span>${state.cases.length}</span></button><button class="tab ${mode==='board'?'active':''}" data-mode="board">Pipeline board</button><span class="tabs-note">${icon('globe')} Singapore booking centre</span></div>${filters()}<div id="case-results">${mode==='list'?caseTable(filtered()):board(filtered())}</div><div class="table-foot"><span id="result-count">${filtered().length} relationships</span> · Changes saved automatically <span>${icon('lock')} Auditable workflow</span></div></section>`;}
function clients(){return heading('RELATIONSHIP INTELLIGENCE','Client directory','One complete view of every client relationship.',btn('New relationship','new-case','plus','primary'))+`<section class="panel">${filters()}<div id="case-results">${caseTable(filtered())}</div></section>`;}
function documentsPage(){const list=state.cases.flatMap(c=>c.documents.map(d=>({...d,client:c.name,caseId:c.id})));return heading('CONNECTED DOCUMENTS','Document centre','Collect, review, and track every document across the client lifecycle.',btn('Upload document','upload-global','upload','primary'))+`<div class="document-summary">${['Pending review','Verified','Rejected'].map(s=>`<div class="panel"><span>${badge(s)}</span><strong>${list.filter(d=>d.status===s).length}</strong><p>documents</p></div>`).join('')}</div><section class="panel"><div class="panel-heading"><div><h2>Document register</h2><p>Open a client case to review supporting evidence</p></div><span class="subtle-pill">${list.length} files</span></div><div class="table-wrap"><table><thead><tr><th>Document</th><th>Client</th><th>Category</th><th>Status</th><th>Uploaded</th><th></th></tr></thead><tbody>${list.map(d=>`<tr><td><div class="file-cell">${icon('file')}<span><strong>${esc(d.name)}</strong><small>${d.sample?'Illustrative sample':Math.ceil(d.size/1024)+' KB'}</small></span></div></td><td><button class="text-btn" data-case="${d.caseId}">${esc(d.client)}</button></td><td>${esc(d.type)}</td><td>${badge(d.status)}</td><td>${date(d.uploadedAt)}</td><td><a class="icon-btn" aria-label="Download ${esc(d.name)}" href="/api/cases/${d.caseId}/documents/${d.id}">${icon('download')}</a></td></tr>`).join('')}</tbody></table></div></section>`;}
function reports(){return heading('LIFECYCLE INTELLIGENCE','The bigger picture, made clear.','Live operational insights calculated from your workspace.',btn('Export CSV','export','download'))+stats()+`<div class="reports-grid"><section class="panel report-panel"><h2>Relationship assets by stage</h2><p>Indicative assets in SGD millions</p><div class="bar-chart">${state.stages.map(s=>{const val=state.cases.filter(c=>c.stage===s).reduce((a,c)=>a+c.aum,0),max=Math.max(1,...state.stages.map(t=>state.cases.filter(c=>c.stage===t).reduce((a,c)=>a+c.aum,0)));return `<div class="bar-row"><span>${esc(s)}</span><div><i style="width:${val/max*100}%"></i></div><b>${val.toFixed(1)}</b></div>`}).join('')}</div></section><section class="panel report-panel"><h2>Risk distribution</h2><p>Know the shape of your client book</p>${['Low','Medium','High'].map(r=>`<div class="risk-report">${badge(r)}<strong>${state.cases.filter(c=>c.risk===r).length}</strong><span>${money(state.cases.filter(c=>c.risk===r).reduce((a,c)=>a+c.aum,0))}</span></div>`).join('')}<div class="info-banner">${icon('chart')} Values reflect demo data, including inactive prospects.</div></section></div><section class="panel report-panel"><h2>Relationship manager workload</h2><div class="table-wrap"><table><thead><tr><th>Relationship manager</th><th>Total relationships</th><th>In onboarding / review</th><th>Indicative assets</th></tr></thead><tbody>${[...new Set(state.cases.map(c=>c.owner))].map(o=>`<tr><td>${esc(o)}</td><td>${state.cases.filter(c=>c.owner===o).length}</td><td>${opened().filter(c=>c.owner===o).length}</td><td>${money(state.cases.filter(c=>c.owner===o).reduce((a,c)=>a+c.aum,0))}</td></tr>`).join('')}</tbody></table></div></section>`;}
function legacysettings(){return heading('YOUR OPERATING MODEL','Workspace settings','Make this workspace fit the way your team works.')+`<div class="settings-grid"><section class="panel settings-panel"><h2>General configuration</h2><p>Changes apply to the workspace and new cases.</p><form id="settings-form"><label>Institution name<input name="bankName" value="${esc(state.settings.bankName)}" required></label><label>Onboarding target (calendar days)<input name="slaDays" type="number" min="1" max="90" value="${state.settings.slaDays}" required></label><label>Booking centre<input value="Singapore" disabled></label><label>Reporting currency<input value="SGD — Singapore dollar" disabled></label><button class="btn primary">Save configuration ${icon('check')}</button></form></section><section class="panel settings-panel"><h2>Integration readiness</h2><p>Connection points for your production environment.</p>${['Identity & access / SSO','Sanctions & PEP screening','Electronic signature','Core banking account creation','Encrypted document storage','Notifications & email delivery'].map(t=>`<div class="integration"><span>${icon('flow')}${t}</span>${badge('Not connected','gray')}</div>`).join('')}<div class="info-banner">${icon('help')} This synthetic demo uses role switching. Use fictional information only.</div></section></div>`;}
function portal(){const c=state.cases[0];return heading('YOUR PRIVATE BANKING JOURNEY',`Welcome, ${esc(c.name.split(' ')[0])}.`,'Your next chapter begins with a few simple steps.',btn('Switch demo role','switch-role','users'))+`<div class="portal-hero"><div><span class="eyebrow">${esc(state.settings.bankName)}</span><h2>A personal welcome.<br>A seamless beginning.</h2><p>Your relationship manager, ${esc(c.owner)}, will guide you through every step.</p>${badge(c.stage)}</div><div class="portal-progress"><strong>${progress(c)}<span>%</span></strong><p>documents verified</p></div></div><div class="portal-steps">${['Your details','Your documents','Our review','Welcome aboard'].map((t,i)=>`<div><span class="${i<2?'current':''}">${i+1}</span>${t}</div>`).join('')}</div>${work.casePanel(c,true)}<section class="panel portal-body"><div class="tabs">${['Overview','Documents','Profile'].map(t=>`<button class="tab ${tab===t?'active':''}" data-portal-tab="${t}">${t==='Overview'?'Your checklist':t==='Profile'?'Your details':t}</button>`).join('')}</div><div class="detail-body">${tab==='Documents'?documentDetail(c):tab==='Profile'?profileForm(c):`<h2>Let’s get you ready.</h2><p class="muted">Complete your profile and upload the documents below.</p>${c.requiredDocuments.map(t=>`<div class="checklist-row"><span class="check-circle ${c.documents.some(d=>d.type===t&&d.status==='Verified')?'done':''}">${icon(c.documents.some(d=>d.type===t)?'check':'file')}</span><div><strong>${esc(t)}</strong><small>${c.documents.some(d=>d.type===t)?'Received · See documents for review status':'Awaiting your upload'}</small></div><button class="text-btn" data-portal-tab="Documents">${c.documents.some(d=>d.type===t)?'View':'Upload'} ${icon('arrow')}</button></div>`).join('')}<div class="info-banner">${icon('lock')} Demo portal: use fictional documents only. The role switch is not production authentication.</div>`}</div></section>`;}
function showCase(id){activeCase=id;tab='Overview';caseModal();}
function caseModal(){const c=state.cases.find(c=>c.id===activeCase);if(!c)return;modal(`<div class="case-header"><div class="client-cell"><span class="avatar client-avatar large">${initials(c.name)}</span><div><div class="eyebrow">${c.id} · ${esc(c.type)}</div><h2>${esc(c.name)}</h2><p>${esc(c.residency)} · ${esc(c.owner)}</p></div></div>${badge(c.risk+' risk',c.risk==='High'?'red':c.risk==='Low'?'green':'amber')}</div><div class="case-stage-line">${c.workflowDefinition.stages.map(s=>s.name).map((s,i)=>`<span class="${s===c.stage?'current':state.stages.indexOf(c.stage)>i?'complete':''}">${icon(state.stages.indexOf(c.stage)>i?'check':s===c.stage?'clock':'chevron')}${esc(s)}</span>`).join('')}</div><div class="tabs">${['Overview','Documents','Profile','Due diligence','Activity'].map(t=>`<button class="tab ${tab===t?'active':''}" data-detail-tab="${t}">${t}${t==='Documents'?` <span>${c.documents.length}</span>`:''}</button>`).join('')}</div><div class="detail-body">${tab==='Overview'?caseOverview(c):tab==='Documents'?documentDetail(c):tab==='Profile'?profileForm(c):tab==='Due diligence'?kycDetail(c):`<h3>Case audit trail</h3><form id="note-form" class="note-form"><input name="note" placeholder="Add a case note…" required maxlength="2000"><button class="btn primary">Add note</button></form>${activities(100,c)}`}</div>`,true);}
function caseOverview(c){const actions=c.availableActions.filter(a=>a.allowed).map(a=>a.label);return `<div class="wealth-quick">${icon('chart')}<div><strong>Source of Wealth · ${esc(c.wealthSummary?.status||'Not started')}</strong><p>Bring the wealth journey, evidence and independent review together.</p></div><button class="btn primary" data-wealth-open="${c.id}">Open wealth assessment ${icon('arrow')}</button></div><div class="case-metrics"><div><span>Current stage</span>${badge(c.stage)}</div><div><span>Indicative assets</span><strong>${money(c.aum)}</strong></div><div><span>Target date</span><strong>${date(c.dueDate)}</strong></div><div><span>Document readiness</span><strong>${progress(c)}%</strong></div></div><div class="detail-columns"><section><h3>Next best actions</h3><p class="muted">Resolve outstanding items to move this relationship forward.</p>${c.blockers.length?c.blockers.map(t=>`<button class="wealth-finding" ${t.includes('Wealth dossier')?'data-wealth-open="'+c.id+'"':'data-detail-tab="'+(/document|uploaded|verified|form must|address must|certification must/i.test(t)?'Documents':/Complete|consent|declaration/i.test(t)?'Profile':'Due diligence')+'"'}>${icon('clock')}<span>${esc(t)}</span>${icon('arrow')}</button>`).join(''):`<div class="info-banner success">${icon('check')} All current policy requirements are satisfied.</div>`}</section><section class="detail-side"><h3>Relationship at a glance</h3><dl><dt>Booking centre</dt><dd>Singapore</dd><dt>Client type</dt><dd>${esc(c.type)}</dd><dt>Tax residency</dt><dd>${esc(c.taxResidency)||'Not provided'}</dd><dt>PEP status</dt><dd>${c.pep?'Declared PEP':'Not declared'}</dd><dt>Created</dt><dd>${date(c.createdAt)}</dd>${c.reviewDate?`<dt>Next review</dt><dd>${date(c.reviewDate)}</dd>`:''}</dl></section></div><div class="detail-action-bar">${actions.map((a,i)=>btn(a,'transition:'+a,i?'refresh':'arrow',i?'secondary':'primary')).join('')}${!actions.length?'<p>No lifecycle action is available for your current role at this stage.</p>':''}</div>${work.casePanel(c)}`;}
function documentDetail(c){const locked=!c.editable;return `<h3>Client documents</h3><p class="muted">${c.requiredDocuments.length} required categories · PDF, JPG or PNG · Maximum ${state.uploadLimitMB||10} MB per file</p>${!locked?`<form id="upload-form"><div class="upload-zone" id="dropzone">${icon('upload')}<strong>Bring your documents together</strong><span>Drag a file here, or select it from your device</span><input type="file" id="upload-file" accept=".pdf,.png,.jpg,.jpeg" required aria-label="Select document file"></div><div class="upload-controls"><select name="type" aria-label="Document category">${[...new Set([...c.requiredDocuments,'Source of wealth evidence'])].map(t=>`<option>${esc(t)}</option>`).join('')}</select><button class="btn primary">${icon('upload')} Upload document</button></div></form>`:''}<div class="document-list">${[...new Set([...c.requiredDocuments,...c.documents.map(d=>d.type)])].map(t=>{const docs=c.documents.filter(d=>d.type===t);return `<div class="doc-group"><h4>${icon('file')}${esc(t)} ${docs.length?'':badge('Required','gray')}</h4>${docs.map(d=>`<div class="doc-row"><div><strong>${esc(d.name)}</strong><small>${d.sample?'Sample placeholder · not real evidence':Math.ceil(d.size/1024)+' KB'} · ${date(d.uploadedAt)}</small>${d.reviewNote?`<small>Review: ${esc(d.reviewNote)}</small>`:''}</div>${badge(d.status)}<a class="icon-btn" aria-label="Download ${esc(d.name)}" href="/api/cases/${c.id}/documents/${d.id}">${icon('download')}</a>${!client()&&!locked&&['Compliance','Operations'].includes(state.session.role)?`<button class="text-btn" data-review="${d.id}">Review</button>`:''}</div>`).join('')||'<p class="muted">No document received yet.</p>'}</div>`}).join('')}</div>`;}
function profileForm(c){const locked=!c.editable;return `<h3>${client()?'Your details':'Client profile'}</h3><p class="muted">Profile changes reset due diligence checks for a fresh review.</p><form id="profile-form"><fieldset ${locked?'disabled':''}><div class="form-grid"><label>Email address<input name="email" type="email" value="${esc(c.email)}" required></label><label>Phone number<input name="phone" value="${esc(c.phone)}"></label><label>Country of residence<input name="residency" value="${esc(c.residency)}" required></label><label>Tax residency<input name="taxResidency" value="${esc(c.taxResidency)}" required></label>${!client()?`<label>Risk classification<select name="risk">${['Low','Medium','High'].map(t=>`<option ${c.risk===t?'selected':''}>${t}</option>`).join('')}</select></label><label>Relationship manager<select name="owner">${['Sarah Chen','James Lim','David Koh'].map(t=>`<option ${c.owner===t?'selected':''}>${t}</option>`).join('')}</select></label>`:''}<label class="full">Source of wealth<textarea name="sourceOfWealth" rows="3" required>${esc(c.sourceOfWealth)}</textarea></label>${!client()?`<label class="checkbox full"><input type="checkbox" name="pep" ${c.pep?'checked':''}> Client is a politically exposed person</label>`:''}${customFormFields(c)}<label class="checkbox full"><input type="checkbox" name="consent" ${c.consent?'checked':''}> ${client()?'I confirm my information is accurate and agree to its use for this demonstration.':'Client declaration has been obtained and recorded.'}</label></div>${!locked?'<button class="btn primary">Save client details</button>':'<p class="muted">Profile is locked at this stage.</p>'}</fieldset></form>`;}
function kycDetail(c){return `<div class="wealth-quick"><div><strong>Wealth assessment · ${esc(c.wealthSummary?.status||'Not started')}</strong><p>Review the dossier before recording the wealth attestation.</p></div><button class="btn secondary" data-wealth-open="${c.id}">Open assessment</button></div><h3>Due diligence review</h3><p class="muted">Record your evidence review. No external screening service is connected.</p>${[['identity','Identity verification','Confirm identity evidence and document validity.'],['screening','Sanctions, PEP & adverse media','Review evidence from your approved screening provider.'],['wealth','Source of wealth & funds','Assess the origin of assets and supporting documentation.'],['tax','Tax & regulatory declarations','Review tax residency and applicable declarations.']].map(([k,t,d])=>`<div class="kyc-row"><span class="check-circle ${c.kyc[k]?'done':''}">${icon(c.kyc[k]?'check':'shield')}</span><div><h4>${t}</h4><p>${d}</p></div><button class="btn ${c.kyc[k]?'secondary':'primary'}" data-kyc="${k}" ${state.session.role!=='Compliance'||!c.canReview?'disabled title="Compliance records decisions during a review stage"':''}>${c.kyc[k]?'Reopen':'Record review'}</button></div>`).join('')}<div class="info-banner">${icon('shield')} Only Compliance can record due diligence decisions.</div>`;}
let previousFocus;
function modal(html,wide=false){previousFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${wide?'Client case':'Workspace dialog'}" tabindex="-1"><button class="modal-close icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button>${html}</section></div>`;bindModal();const title=$('.modal h2');if(title){title.id='dialog-title';$('.modal').setAttribute('aria-labelledby','dialog-title');}$('.modal').focus();document.body.classList.add('modal-open');}
function closeModal(){$('#modal-root').innerHTML='';document.body.classList.remove('modal-open');previousFocus?.focus();}
function newCase(){modal(`<div class="modal-title"><span class="stat-icon blue">${icon('users')}</span><div class="eyebrow">A NEW RELATIONSHIP</div><h2>Great journeys start here.</h2><p>Create an onboarding case. We’ll guide you through the rest.</p></div><form id="new-case-form"><div class="form-grid"><label class="full">Client / entity name<input name="name" placeholder="e.g. Amelia Tan" required maxlength="120"></label><label>Email address<input name="email" type="email" placeholder="client@example.com" required></label><label>Client type<select name="type"><option>Individual</option><option>Company</option><option>Family office</option></select></label><label>Country of residence<input name="residency" value="Singapore" required></label><label>Risk classification<select name="risk"><option>Low</option><option>Medium</option><option>High</option></select></label><label>Indicative assets (SGD millions)<input name="aum" type="number" min="0" max="100000" step="0.1" placeholder="5.0" required></label><label>Relationship manager<select name="owner"><option>Sarah Chen</option><option>James Lim</option><option>David Koh</option></select></label><label class="checkbox full"><input name="pep" type="checkbox"> Politically exposed person</label></div><div class="form-footer"><span>${icon('lock')} Fictional client data only</span><button class="btn primary">Create onboarding ${icon('arrow')}</button></div></form>`);}
function roleModal(){modal(`<div class="modal-title"><span class="eyebrow">DEMO WORKSPACE</span><h2>Explore a different perspective.</h2><p>Role switching is a demonstration tool, not authentication.</p></div><form id="role-form"><label>Workspace role<select name="role">${['Relationship manager','Compliance','Operations','Client'].map(t=>`<option ${state.session.role===t?'selected':''}>${t}</option>`).join('')}</select></label><label>Client portal identity<select name="clientId">${state.cases.map(c=>`<option value="${c.id}" ${state.session.clientId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><div class="info-banner">${icon('help')} Relationship managers prepare cases. Operations reviews documents. Compliance records due diligence and approves cases. Clients access only their selected case.</div><button class="btn primary">Enter workspace ${icon('arrow')}</button></form>`);}
function help(){modal(`<div class="modal-title"><span class="eyebrow">WELCOME TO AURELIA</span><h2>A connected client lifecycle.</h2><p>A synthetic demonstration inspired by leading CLM platforms.</p></div><div class="help-list"><p><b>1. Create a relationship.</b> Add a client, choose the risk and client type, then complete the profile.</p><p><b>2. Collect evidence.</b> Switch to the client portal to upload forms. Operations or Compliance can verify them.</p><p><b>3. Review and approve.</b> Submit for due diligence, record four checks, then let a relationship manager request independent Compliance approval.</p><p><b>4. Manage the lifecycle.</b> Activate, open periodic reviews, and offboard with a recorded reason.</p></div><div class="resource-links"><a href="https://www.fenergo.com/client-lifecycle-management" target="_blank" rel="noreferrer">Fenergo · Policy-driven journeys ↗</a><a href="https://wealth-dynamix.com/wp-content/uploads/2020/06/eBook-What-is-Client-Lifecycle-Management.pdf" target="_blank" rel="noreferrer">Wealth Dynamix · Connected workflows ↗</a><a href="https://investcloud.com/what-we-do/front-office-solutions/client-solutions/" target="_blank" rel="noreferrer">InvestCloud · Guided client experience ↗</a></div><div class="info-banner">${icon('lock')} Production requires SSO, encrypted storage, malware scanning, screening integrations, retention controls and a validated bank policy.</div>`);}
async function mutate(url,method,data,message){await api(url,method,data);state=await api('/state');render();toast(message);}
function current(){return client()?state.cases[0]:state.cases.find(c=>c.id===activeCase);}
function bindBase(){document.querySelectorAll('[data-page]').forEach(e=>e.onclick=()=>{page=e.dataset.page;query='';stageFilter='All stages';riskFilter='All risks';render();});$('.brand')?.addEventListener('click',e=>{e.preventDefault();page=client()?'Client portal':'Overview';render();});document.querySelectorAll('[data-action]').forEach(e=>e.onclick=()=>action(e.dataset.action));document.querySelectorAll('[data-stage]').forEach(e=>e.onclick=()=>{page='Onboarding';stageFilter=e.dataset.stage;render();});document.querySelectorAll('[data-mode]').forEach(e=>e.onclick=()=>{mode=e.dataset.mode;render();});bindCaseLinks();$('#case-search')?.addEventListener('input',e=>{query=e.target.value;$('#case-results').innerHTML=mode==='board'&&page==='Onboarding'?board(filtered()):caseTable(filtered());if($('#result-count'))$('#result-count').textContent=filtered().length+' relationships';bindCaseLinks();});$('#stage-filter')?.addEventListener('change',e=>{stageFilter=e.target.value;render();});$('#risk-filter')?.addEventListener('change',e=>{riskFilter=e.target.value;render();});document.querySelectorAll('[data-rule]').forEach(e=>e.onclick=async()=>{try{await mutate('/rules','PUT',{revision:state.revision,rules:state.rules.map(r=>r.id===e.dataset.rule?{...r,enabled:!r.enabled}:r)},'Policy updated');}catch(err){toast(err.message,true);}});document.querySelectorAll('[data-edit-rule]').forEach(e=>e.onclick=()=>ruleModal(e.dataset.editRule));$('#settings-form')?.addEventListener('submit',async e=>{e.preventDefault();try{await mutate('/settings','PUT',Object.fromEntries(new FormData(e.target)),'Workspace settings saved');}catch(err){toast(err.message,true);}});if(client())bindDetail(document);}
function bindCaseLinks(){document.querySelectorAll('[data-case]').forEach(e=>{e.onclick=()=>showCase(e.dataset.case);e.onkeydown=k=>{if(k.key==='Enter'){k.preventDefault();showCase(e.dataset.case);}};});}
async function baseAction(a){try{if(a==='new-case')return newCase();if(a==='close-modal')return closeModal();if(a==='switch-role')return roleModal();if(a==='help')return help();if(a==='new-rule')return ruleModal();if(a==='reset-filters'){query='';stageFilter='All stages';riskFilter='All risks';return render();}if(a==='go-rules'){page='Rules & policies';return render();}
if(a==='notifications'){modal(`<div class="modal-title"><div class="eyebrow">ATTENTION QUEUE</div><h2>A little attention. A big difference.</h2><p>Open cases due within three days.</p></div>${opened().filter(c=>days(c)<=3).map(c=>`<button class="attention-row" data-case="${c.id}"><span><strong>${esc(c.name)}</strong><small>${c.id} · ${date(c.dueDate)}</small></span>${badge(days(c)<0?'Overdue':'Due soon','amber')}${icon('arrow')}</button>`).join('')||'<p>All caught up. No cases due soon.</p>'}`);bindCaseLinks();return;}
if(a==='export'){const rows=[['Case ID','Client','Stage','Risk','Assets SGD millions','Owner','Target date'],...state.cases.map(c=>[c.id,c.name,c.stage,c.risk,c.aum,c.owner,c.dueDate])],csv=rows.map(r=>r.map(v=>'"'+String(v).replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n'),u=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=u;link.download='aurelia-client-lifecycle.csv';link.click();setTimeout(()=>URL.revokeObjectURL(u),1000);return toast('Lifecycle report exported');}
if(a==='upload-global'){modal(`<div class="modal-title"><h2>Select a client case</h2><p>Documents are linked to a relationship.</p></div><form id="select-case-form"><label>Client<select name="caseId">${opened().filter(c=>c.stage!=='Approval').map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><button class="btn primary">Continue ${icon('arrow')}</button></form>`);$('#select-case-form').onsubmit=e=>{e.preventDefault();activeCase=new FormData(e.target).get('caseId');tab='Documents';caseModal();};return;}
if(a.startsWith('transition:')){const display=a.slice(11),c=current(),route=c.availableActions.find(x=>x.label===display),value=route?.id||display;modal(`<div class="modal-title"><span class="eyebrow">${c.id}</span><h2>${esc(display)}</h2><p>${esc(c.name)} · ${esc(state.session.role)}</p></div><form id="transition-form"><label>Decision note<textarea name="note" rows="3" placeholder="Record the context for this decision…" ${route?.guards.includes('reason')?'required minlength="8"':''}></textarea></label><div class="info-banner">${icon('shield')} Policy and approval controls are checked before the case can move forward.</div><button class="btn primary">Confirm ${icon('arrow')}</button></form>`);$('#transition-form').onsubmit=async e=>{e.preventDefault();try{await mutate(`/cases/${c.id}/transition`,'POST',{action:value,note:new FormData(e.target).get('note')},'Case stage updated');tab='Overview';caseModal();}catch(err){toast(err.message,true);}};}
}catch(err){toast(err.message,true);}}
function bindModalBase(){const root=$('#modal-root');root.querySelectorAll('[data-action]').forEach(e=>e.onclick=()=>action(e.dataset.action));$('.modal-overlay').onclick=e=>{if(e.target===e.currentTarget)closeModal();};$('#new-case-form')?.addEventListener('submit',async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));data.pep=!!data.pep;try{const c=await api('/cases','POST',data);await load();showCase(c.id);toast('New onboarding case created');}catch(err){toast(err.message,true);}});$('#role-form')?.addEventListener('submit',async e=>{e.preventDefault();try{await api('/session','POST',Object.fromEntries(new FormData(e.target)));page='Overview';tab='Overview';wealth.reset();closeModal();await load();toast('Workspace role updated');}catch(err){toast(err.message,true);}});$('#rule-form')?.addEventListener('submit',async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target)),id=e.target.dataset.id,rules=id?state.rules.map(r=>r.id===id?{...r,...data}:r):[...state.rules,{...data,enabled:true}];try{await mutate('/rules','PUT',{rules},'Document rule saved');closeModal();}catch(err){toast(err.message,true);}});bindDetail(root);}
function bindDetail(root){root.querySelectorAll('[data-detail-tab]').forEach(e=>e.onclick=()=>{tab=e.dataset.detailTab;caseModal();});root.querySelectorAll('[data-portal-tab]').forEach(e=>e.onclick=()=>{tab=e.dataset.portalTab;render();});const c=current();if(!c)return;
root.querySelector('#profile-form')?.addEventListener('submit',async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));data.consent=!!data.consent;if(!client())data.pep=!!data.pep;data.customFields=readCustomFields(e.target,c);try{await mutate(`/cases/${c.id}`,'PATCH',data,'Client profile saved');if(!client())caseModal();}catch(err){toast(err.message,true);}});
root.querySelector('#note-form')?.addEventListener('submit',async e=>{e.preventDefault();try{await mutate(`/cases/${c.id}/notes`,'POST',Object.fromEntries(new FormData(e.target)),'Note added to audit trail');caseModal();}catch(err){toast(err.message,true);}});
const drop=root.querySelector('#dropzone');if(drop){drop.ondragover=e=>{e.preventDefault();drop.classList.add('dragover');};drop.ondragleave=()=>drop.classList.remove('dragover');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('dragover');$('#upload-file',root).files=e.dataTransfer.files;};}
root.querySelector('#upload-form')?.addEventListener('submit',async e=>{e.preventDefault();const file=$('#upload-file',root).files[0];if(!file)return;if(file.size>(state.uploadLimitMB||10)*1024*1024)return toast(`Maximum file size is ${state.uploadLimitMB||10} MB`,true);const button=e.target.querySelector('button');button.disabled=true;button.textContent='Uploading…';try{const content=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});await mutate(`/cases/${c.id}/documents`,'POST',{name:file.name,type:new FormData(e.target).get('type'),content},'Document uploaded for review');if(!client())caseModal();}catch(err){toast(err.message,true);button.disabled=false;button.textContent='Upload document';}});
root.querySelectorAll('[data-review]').forEach(e=>e.onclick=()=>{const d=c.documents.find(d=>d.id===e.dataset.review);modal(`<div class="modal-title"><div class="eyebrow">DOCUMENT REVIEW</div><h2>${esc(d.type)}</h2><p>${esc(d.name)}</p></div><form id="review-form"><label>Outcome<select name="status"><option>Verified</option><option>Rejected</option></select></label><label>Evidence / reason<textarea name="note" rows="3" required placeholder="Record evidence or a rejection reason"></textarea></label><button class="btn primary">Save review ${icon('check')}</button></form>`);$('#review-form').onsubmit=async e=>{e.preventDefault();try{await mutate(`/cases/${c.id}/documents/${d.id}/review`,'POST',Object.fromEntries(new FormData(e.target)),'Document review recorded');tab='Documents';caseModal();}catch(err){toast(err.message,true);}};});
root.querySelectorAll('[data-kyc]').forEach(e=>e.onclick=()=>{const check=e.dataset.kyc;modal(`<div class="modal-title"><div class="eyebrow">DUE DILIGENCE</div><h2>${c.kyc[check]?'Reopen':'Complete'} ${check} review</h2><p>Record the source and outcome of your human review.</p></div><form id="kyc-form"><label>Review evidence<textarea name="note" required rows="4" placeholder="Evidence reference, checks performed and findings…"></textarea></label><button class="btn primary">Record decision ${icon('check')}</button></form>`);$('#kyc-form').onsubmit=async e=>{e.preventDefault();try{await mutate(`/cases/${c.id}/kyc`,'PUT',{check,checked:!c.kyc[check],note:new FormData(e.target).get('note')},'Due diligence review recorded');tab='Due diligence';caseModal();}catch(err){toast(err.message,true);}};});}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('.modal')){const nodes=[...$('.modal').querySelectorAll('button,a,input,select,textarea,[tabindex="0"]')].filter(n=>!n.disabled&&n.offsetParent!==null),first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('.modal'))){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
load().catch(err=>{$('#app').innerHTML='<div class="boot">Unable to load workspace.<span>'+esc(err.message)+'</span></div>';});
function customFormFields(c){return state.ui.customFields.map(f=>{const v=c.customFields?.[f.key]??'',disabled=client()&&!f.clientEditable?'disabled':'',key='custom_'+f.key,required=c.requiredFields.includes(f.key)?' *':'';let field=f.type==='textarea'?`<textarea name="${key}" ${disabled}>${esc(v)}</textarea>`:f.type==='select'?`<select name="${key}" ${disabled}><option value="">Choose…</option>${f.options.map(x=>`<option ${v===x?'selected':''}>${esc(x)}</option>`).join('')}</select>`:f.type==='checkbox'?`<input type="checkbox" name="${key}" ${v?'checked':''} ${disabled}>`:`<input name="${key}" type="${f.type==='number'?'number':f.type==='date'?'date':'text'}" value="${esc(v)}" ${disabled}>`;return `<label class="${f.type==='checkbox'?'checkbox full':''}">${esc(f.label)}${required}${field}</label>`;}).join('');}
function readCustomFields(form,c){const output={};for(const f of state.ui.customFields){if(client()&&!f.clientEditable)continue;const el=form.elements['custom_'+f.key];if(!el)continue;output[f.key]=f.type==='checkbox'?el.checked:f.type==='number'&&el.value!==''?Number(el.value):el.value;}return output;}
function conditionText(group){return group.items.length?group.items.map(x=>`${x.field} ${x.op} ${x.value}`).join(group.match==='all'?' AND ':' OR '):'Always';}
function workflows(){return studio.workflow();}
function rulesPage(){return heading('POLICY STUDIO','Rules that adapt to your clients.','Combine conditions and require documents or custom form fields.',btn('Add a rule','new-rule','plus','primary'))+`<div class="info-banner">${icon('shield')} Rules apply immediately. Core identity, address, account and tax documents always remain required.</div><div class="rules-grid">${state.rules.map(r=>`<section class="panel rule-card"><div class="rule-top"><span class="stat-icon blue">${icon('shield')}</span><button class="toggle ${r.enabled?'on':''}" data-rule="${esc(r.id)}" role="switch" aria-checked="${r.enabled}" aria-label="Toggle ${esc(r.name)}"><span></span></button></div><h2>${esc(r.name)}</h2><p>${esc(r.description)}</p><div class="condition-summary">${esc(conditionText(r.conditions))}</div>${r.documents.map(d=>`<div class="rule-result">${icon('file')}${esc(d)}</div>`).join('')}<div class="rule-foot">${r.enabled?'Enabled':'Disabled'}<button class="text-btn" data-edit-rule="${esc(r.id)}">Edit policy</button></div></section>`).join('')}</div>`;}
function ruleModal(id){return studio.policy(id);}
function settings(){return legacysettings()+studio.settingsPanel();}
function bind(){bindBase();studio.bind();wealth.bind();work.bind();const cards=[...document.querySelectorAll('.stats-grid .stat-card')];cards.forEach((c,i)=>{if(!state.ui.dashboardCards.includes(['open','approval','attention','assets'][i]))c.remove();});document.querySelectorAll('.stats-grid').forEach(g=>g.style.gridTemplateColumns=`repeat(${Math.max(1,state.ui.dashboardCards.length)},minmax(0,1fr))`);}
function bindModal(){bindModalBase();wealth.bind();work.bind();}
async function action(a){try{
 if(work.action(a))return;
 if(await wealth.action(a))return;
 if(await studio.action(a))return;
 if(a==='config-export'){const config=await api('/config/export'),u=URL.createObjectURL(new Blob([JSON.stringify(config,null,2)],{type:'application/json'})),link=document.createElement('a');link.href=u;link.download='aurelia-configuration.json';link.click();setTimeout(()=>URL.revokeObjectURL(u),1000);return;}
 if(a==='wf-validate'){const r=await api('/workflow/validate','POST',{});return toast(r.message);}
 if(a==='wf-publish'){modal(`<div class="modal-title"><h2>Publish workflow v${state.workflow.version+1}</h2><p>Existing cases retain their version. New cases use this published journey.</p></div><form id="publish-v2"><label>Publication note<textarea name="note" required></textarea></label><button class="btn primary">Publish workflow</button></form>`);$('#publish-v2').onsubmit=async e=>{e.preventDefault();try{await mutate('/workflow/publish','POST',{draftRevision:state.draftRevision,note:new FormData(e.target).get('note')},'Workflow published');closeModal();}catch(err){toast(err.message,true);}};return;}
 if(a.startsWith('wf-stage:')){const i=Number(a.split(':')[1]),w=structuredClone(state.workflowDraft),s=w.stages[i];modal(`<div class="modal-title"><h2>Configure ${esc(s.name)}</h2></div><form id="stage-v2"><label>Stage name<input name="name" value="${esc(s.name)}" required></label><label>Owner<select name="owner">${state.schema.staff.map(x=>`<option ${x===s.owner?'selected':''}>${x}</option>`).join('')}</select></label><label>Target days<input type="number" min="1" max="365" name="slaDays" value="${s.slaDays}"></label><label>Team guidance<textarea name="description">${esc(s.description)}</textarea></label><label class="checkbox"><input name="editable" type="checkbox" ${s.editable?'checked':''} ${['active','approval','closed'].includes(s.kind)?'disabled':''}>Allow changes in this stage</label><button class="btn primary">Save to draft</button></form>`);$('#stage-v2').onsubmit=async e=>{e.preventDefault();try{const f=new FormData(e.target),old=s.name,name=f.get('name');if(w.stages.some((x,j)=>j!==i&&x.name===name))throw Error('Stage names must be unique');Object.assign(s,{name,owner:f.get('owner'),slaDays:Number(f.get('slaDays')),description:f.get('description'),editable:f.has('editable')});w.transitions.forEach(r=>{if(r.source===old)r.source=name;if(r.target===old)r.target=name;});if(w.startStage===old)w.startStage=name;await mutate('/workflow/draft','PUT',{workflow:w,draftRevision:state.draftRevision},'Draft stage saved');closeModal();}catch(err){toast(err.message,true);}};return;}
 if(a.startsWith('wf-route:')){const which=a.split(':')[1],w=structuredClone(state.workflowDraft),r=which==='new'?{id:crypto.randomUUID(),label:'Continue',source:w.stages[0].name,target:w.stages[1].name,roles:['Relationship manager'],guards:[],conditions:{match:'all',items:[]},resetChecks:false}:w.transitions[Number(which)];modal(`<div class="modal-title"><h2>Configure route</h2></div><form id="route-v2"><label>Action label<input name="label" value="${esc(r.label)}" required></label><div class="form-grid">${['source','target'].map(k=>`<label>${k==='source'?'From':'To'}<select name="${k}">${w.stages.map(s=>`<option ${r[k]===s.name?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label>`).join('')}</div><h3>Who can act?</h3>${state.schema.staff.map(x=>`<label class="checkbox"><input type="checkbox" name="roles" value="${x}" ${r.roles.includes(x)?'checked':''}>${x}</label>`).join('')}<h3>Required checks</h3>${Object.entries(state.schema.guards).map(([k,v])=>`<label class="checkbox"><input type="checkbox" name="guards" value="${k}" ${r.guards.includes(k)?'checked':''}>${v}</label>`).join('')}<label class="checkbox"><input type="checkbox" name="reset" ${r.resetChecks?'checked':''}>Reset due diligence checks</label><label>Condition group (JSON)<textarea rows="5" name="conditions">${esc(JSON.stringify(r.conditions,null,2))}</textarea></label><button class="btn primary">Save route to draft</button></form>`);$('#route-v2').onsubmit=async e=>{e.preventDefault();try{const f=new FormData(e.target);Object.assign(r,{label:f.get('label'),source:f.get('source'),target:f.get('target'),roles:f.getAll('roles'),guards:f.getAll('guards'),resetChecks:f.has('reset'),conditions:JSON.parse(f.get('conditions'))});if(which==='new')w.transitions.push(r);await mutate('/workflow/draft','PUT',{workflow:w,draftRevision:state.draftRevision},'Route saved; validate before publishing');closeModal();}catch(err){toast(err.message,true);}};return;}
 if(a==='wf-json'||a==='ui-edit'){const ui=a==='ui-edit',value=ui?state.ui:state.workflowDraft;modal(`<div class="modal-title"><h2>${ui?'Interface configuration':'Full workflow draft'}</h2><p>${ui?'Edit branding, navigation, cards and custom fields.':'Edit stages, display order and routing. Validate before publishing.'}</p></div><form id="config-v2"><label>Configuration JSON<textarea name="json" rows="20" spellcheck="false">${esc(JSON.stringify(value,null,2))}</textarea></label><button class="btn primary">Save ${ui?'configuration':'draft'}</button></form>`,true);$('#config-v2').onsubmit=async e=>{e.preventDefault();try{const value=JSON.parse(new FormData(e.target).get('json'));await mutate(ui?'/ui':'/workflow/draft','PUT',ui?{ui:value,revision:state.revision}:{workflow:value,draftRevision:state.draftRevision},'Configuration saved');closeModal();}catch(err){toast(err.message,true);}};return;}
 return baseAction(a);
 }catch(err){toast(err.message,true);}}
